def erase_overlap_intervals(intervals):
    intervals.sort(key=lambda iv: iv[1])   # earliest finish first
    removed = 0
    last_end = float("-inf")
    for start, end in intervals:
        if start < last_end:
            removed += 1                   # overlap: drop this one
        else:
            last_end = end
    return removed

